//! The board's sample texts, run by run (generated by script from the goldens of DW-1512 and
//! DW-1527: text, ink, bold, italic, underline, exactly as the board draws them). The board colours
//! its samples by hand; a tokenizer for real files is a follow-up named in the PR body.

use super::source::{Ink, Run};

/// Flags: 1 bold, 2 italic, 4 underlined.
fn r(text: &str, ink: Ink, flags: u8) -> Run {
    Run {
        text: text.to_string(),
        ink,
        bold: flags & 1 != 0,
        italic: flags & 2 != 0,
        underline: flags & 4 != 0,
    }
}

/// DW-1512: export_invoices.py.
#[rustfmt::skip]
pub fn python() -> Vec<Vec<Run>> {
    vec![
        vec![r("# Export this month's invoices as one CSV", Ink::Faint, 2)],
        vec![r("import", Ink::Strong, 1), r(" csv", Ink::Plain, 0)],
        vec![r("from", Ink::Strong, 1), r(" pathlib ", Ink::Plain, 0), r("import", Ink::Strong, 1), r(" Path", Ink::Plain, 0)],
        vec![],
        vec![r("def", Ink::Strong, 1), r(" export_invoices", Ink::Strong, 4), r("(folder: Path, month: ", Ink::Plain, 0), r("\"2026-11\"", Ink::Green, 0), r("):", Ink::Plain, 0)],
        vec![r("    rows = []", Ink::Plain, 0)],
        vec![r("    for", Ink::Strong, 1), r(" f ", Ink::Plain, 0), r("in", Ink::Strong, 1), r(" sorted(folder.glob(", Ink::Plain, 0), r("\"Invoice *.pdf\"", Ink::Green, 0), r(")):", Ink::Plain, 0)],
        vec![r("        number = ", Ink::Plain, 0), r("int", Ink::Strong, 4), r("(f.stem.split()[", Ink::Plain, 0), r("1", Ink::Red, 0), r("])", Ink::Plain, 0)],
        vec![r("        rows.append({", Ink::Plain, 0), r("\"number\"", Ink::Green, 0), r(": number, ", Ink::Plain, 0), r("\"file\"", Ink::Green, 0), r(": f.name})", Ink::Plain, 0)],
        vec![r("    with", Ink::Strong, 1), r(" open(", Ink::Plain, 0), r("\"invoices.csv\"", Ink::Green, 0), r(", ", Ink::Plain, 0), r("\"w\"", Ink::Green, 0), r(") ", Ink::Plain, 0), r("as", Ink::Strong, 1), r(" out:", Ink::Plain, 0)],
        vec![r("        w = csv.DictWriter(out, fieldnames=[", Ink::Plain, 0), r("\"number\"", Ink::Green, 0), r(", ", Ink::Plain, 0), r("\"file\"", Ink::Green, 0), r("])", Ink::Plain, 0)],
        vec![r("        w.writeheader()", Ink::Plain, 0)],
        vec![r("        w.writerows(rows)", Ink::Plain, 0)],
        vec![r("    return", Ink::Strong, 1), r(" len(rows)", Ink::Plain, 0)],
        vec![],
        vec![r("if", Ink::Strong, 1), r(" __name__ == ", Ink::Plain, 0), r("\"__main__\"", Ink::Green, 0), r(":", Ink::Plain, 0)],
        vec![r("    count = export_invoices(Path(", Ink::Plain, 0), r("\"Invoices 2026\"", Ink::Green, 0), r("))", Ink::Plain, 0)],
        vec![r("    print(", Ink::Plain, 0), r("f\"Exported {count} invoices\"", Ink::Green, 0), r(")", Ink::Plain, 0)],
    ]
}

